#pragma once
#include "ui_settings.h"
enum class AppSetting {Volume,Equalizer,MicTest,Sensitivity,Quality,HudTimeout,Stats,Style,Colour,Font,DebugComparison,Credits};
inline const char *appSettingsTabName(int tab){static const char *names[]={"Music","Visualizers","Theme","Misc"};return names[UiSettings::bound(tab,0,3)];}
inline int appSettingsRowCount(int tab){return tab==3?5:tab==2?3:2;}
inline AppSetting appSettingsAction(int tab,int row){static const AppSetting rows[4][5]={{AppSetting::Volume,AppSetting::Equalizer},{AppSetting::Sensitivity,AppSetting::Quality},{AppSetting::Style,AppSetting::Colour,AppSetting::Font},{AppSetting::HudTimeout,AppSetting::Stats,AppSetting::DebugComparison,AppSetting::MicTest,AppSetting::Credits}};return rows[UiSettings::bound(tab,0,3)][UiSettings::bound(row,0,appSettingsRowCount(tab)-1)];}
inline const char *appSettingLabel(AppSetting setting){switch(setting){case AppSetting::Volume:return "Volume";case AppSetting::Equalizer:return "Equalizer";case AppSetting::MicTest:return "Mic test";case AppSetting::Sensitivity:return "Sensitivity";case AppSetting::Quality:return "MilkDrop quality";case AppSetting::HudTimeout:return "HUD auto-hide";case AppSetting::Stats:return "FPS / temperature";case AppSetting::Style:return "Interface style";case AppSetting::Colour:return "Colour";case AppSetting::Font:return "Font";case AppSetting::DebugComparison:return "Debug comparison";default:return "Credits";}}
inline void appSettingValue(char *out,unsigned size,AppSetting s,const UiSettings &ui,bool hd,int sensitivity){switch(s){case AppSetting::Volume:snprintf(out,size,ui.audio.muted?"Muted - %d%%":"%d%%",ui.audio.volume);break;case AppSetting::Equalizer:snprintf(out,size,"%s - X Open",!ui.audio.eqEnabled?"Off":ui.audio.isFlat()?"Flat":"Custom");break;case AppSetting::Sensitivity:snprintf(out,size,"%.2f x",.5f+sensitivity*.25f);break;case AppSetting::Quality:snprintf(out,size,"%s - after relaunch",hd?"1080p":"288p");break;case AppSetting::HudTimeout:snprintf(out,size,"%d seconds",ui.hudSeconds);break;case AppSetting::Stats:snprintf(out,size,"%s",ui.stats?"On":"Off");break;case AppSetting::Style:snprintf(out,size,"%s",ui.styleName());break;case AppSetting::Colour:snprintf(out,size,"%s",ui.themeName());break;case AppSetting::Font:snprintf(out,size,"%s",ui.fontName());break;default:snprintf(out,size,"X Open");break;}}
